import { printHTML } from '../../utils/printHelper';
import { primaryActionButtonStyle, primaryActionBtnEnter, primaryActionBtnLeave } from './primaryActionButtonStyle';
import { getSitePrintConfig } from '../../utils/siteConfig';
const GMT_LOGO  = "data:image/png;base64,";
const CERT_LOGO = "data:image/jpeg;base64,";

const EXAMENS = [
  { key: 'visiotest',   label: 'VISIOTEST' },
  { key: 'audiogramme', label: 'AUDIOGRAMME' },
  { key: 'ecg',         label: 'ECG' },
  { key: 'efr',         label: 'EFR' },
];

export function buildExamenHTML(fiche, form, siteConfigInput) {
  const ex = form || {};
  const fi = fiche || {};
  const siteConfig = getSitePrintConfig(siteConfigInput, fi, ex);

  let age = '';
  if (fi.collaborateur_date_naissance) {
    const born = new Date(fi.collaborateur_date_naissance);
    age = Math.floor((new Date() - born) / (365.25 * 24 * 3600 * 1000));
  }
  const fmt = (d) => d ? new Date(d).toLocaleDateString('fr-FR') : '';

  const nom  = fi.collaborateur_nom       || '';
  const mat  = fi.collaborateur_matricule || '';
  const ent  = fi.raison_sociale          || '';
  const post = fi.collaborateur_poste     || '';
  const gsm  = fi.collaborateur_telephone || ex.collaborateur_gsm || '';
  const date = fmt(ex.date_demande || fi.date_visite);
  const col  = '#1e3a5f';
  const rawRens = ex.renseignements_cliniques || '';
  const rens = String(rawRens)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\r?\n/g, '<br/>');
  const cboxes = EXAMENS.map(a => {
    const chk = ex[a.key] ? 'cb-on' : '';
    return `<div class="check-row"><span class="cb ${chk}"></span><span>${a.label}</span></div>`;
  }).join('');

  return `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"/>
<title>Examens Complementaires</title>
<style>
@page { size: A4 portrait; margin: 12mm 15mm 12mm 15mm; }
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: Arial, sans-serif; font-size: 10.5pt; color: ${col}; background: white; display: flex; flex-direction: column; min-height: calc(297mm - 24mm); }
.header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.header-left { font-size: 9pt; font-weight: bold; line-height: 1.6; }
.header-center { text-align: center; flex: 1; }
.header-right { text-align: right; font-size: 9pt; line-height: 1.6; }
.ref-box { border: 2px solid ${col}; padding: 2px 8px; font-size: 9pt; font-weight: 900; display: inline-block; margin-bottom: 4px; }
.title { text-align: center; font-size: 13pt; font-weight: 900; text-transform: uppercase; margin: 10px 0 12px; letter-spacing: .5px; }
.field-row { display: flex; gap: 16px; margin-bottom: 6px; }
.field { display: flex; align-items: flex-end; gap: 4px; flex: 1; }
.fl { font-weight: 700; white-space: nowrap; font-size: 9.5pt; }
.fv { border-bottom: 1px dotted ${col}; flex: 1; min-width: 40px; font-size: 9.5pt; }
.section-title { font-size: 10.5pt; font-weight: 900; text-decoration: underline; margin: 12px 0 8px; }
.cb { display: inline-block; width: 14px; height: 14px; border: 1.5px solid ${col}; vertical-align: middle; text-align: center; font-size: 10pt; line-height: 13px; margin-right: 6px; }
.cb-on::after { content: "\u2713"; color: ${col}; font-weight: bold; }
.check-row { display: flex; align-items: center; margin-bottom: 10px; font-size: 10.5pt; }
.dotline { border-bottom: 1px dotted ${col}; display: block; width: 100%; height: 18px; margin-bottom: 6px; }
.footer { display: flex; align-items: flex-end; justify-content: space-between; margin-top: 30px; }
.footer-center { text-align: center; flex: 1; font-size: 9.5pt; font-weight: bold; }
.footer-sign { text-align: center; font-size: 9.5pt; font-weight: bold; margin-top: 4px; }
</style></head><body>

<div class="header">
  <div class="header-left">${siteConfig.medicalServiceName || 'Service Medical'}<br/>${siteConfig.footerCompanySite || 'Leoni Menzel Hayet'}</div>
  <div class="header-center">
    <img src="${GMT_LOGO}" style="height:80px;width:auto;display:block;margin:0 auto;" alt="GMT"/>
    <div style="font-size:8pt;margin-top:2px;">Certifie ISO 9001 : 2008</div>
  </div>
  <div class="header-right">
    <div class="ref-box">FR - VME - 03/03</div>
    <div style="direction:rtl;text-align:right;font-size:9pt;font-weight:bold;line-height:1.6;">&#x645;&#x62C;&#x645;&#x639; &#x637;&#x628; &#x627;&#x644;&#x634;&#x63A;&#x644;<br/>&#x628;&#x648;&#x644;&#x627;&#x64A;&#x629; &#x627;&#x644;&#x645;&#x646;&#x633;&#x62A;&#x64A;&#x631;</div>
  </div>
</div>

<div class="title">Demande d'Examens Complementaires</div>

<div class="field-row">
  <div class="field"><span class="fl">NOM ET PRENOM :</span><span class="fv">${nom}</span></div>
  <div class="field" style="flex:0 0 auto;gap:8px;">
    <span class="fl">AGE :</span><span class="fv" style="min-width:28px;">${age}</span>
    <span class="fl">M<sup>le</sup> :</span><span class="fv" style="min-width:55px;">${mat}</span>
  </div>
</div>
<div class="field-row">
  <div class="field"><span class="fl">ENTREPRISE :</span><span class="fv">${ent}</span></div>
  <div class="field"><span class="fl">GSM :</span><span class="fv">${gsm}</span></div>
</div>
<div class="field-row">
  <div class="field"><span class="fl">POSTE DE TRAVAIL :</span><span class="fv">${post}</span></div>
</div>

<div class="field-row" style="align-items:flex-start;margin-top:8px;">
  <div class="field" style="align-items:flex-start;flex-wrap:wrap;">
    <span class="fl" style="padding-top:2px;">RENSEIGNEMENTS CLINIQUES :</span>
    <span class="fv" style="min-height:40px;white-space:normal;line-height:1.45;">${rens || '&nbsp;'}</span>
  </div>
</div>

<div class="section-title">RENSEIGNEMENTS COMPLEMENTAIRES :</div>
${cboxes}

<div style="text-align:center;margin-top:24px;font-size:9.5pt;font-weight:bold;">
  DATE : ${date || '......................................................'}
</div>
<div style="text-align:center;font-size:9.5pt;font-weight:bold;margin-top:4px;">
  CACHET ET SIGNATURE DU MEDECIN DU TRAVAIL
</div>

<div style="margin-top:auto;padding-top:30px;">
  <div style="border-top:1.5px solid #1e3a5f;padding-top:8px;display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;column-gap:10px;font-size:8.5pt;">
      <img src="${CERT_LOGO}" style="height:40px;width:auto;justify-self:start;align-self:center;" alt="cert"/>
      <div style="text-align:center;font-size:8pt;line-height:1.55;font-weight:700;padding:0 6px;">Zone Industrielle Route de Khnis - Monastir — Boîte postale N° 41 — Poste gare Monastir — 5097<br/>Tél : 73 508 100 / Fax : 73 508 101</div>
      <div aria-hidden="true"></div>
  </div>
</div>

</body></html>`;
}

export default function PrintExamen({ fiche, form }) {
  function handlePrint() {
    const html = buildExamenHTML(fiche, form);
    printHTML(html);
  }
  return (
    <button onClick={handlePrint} title="Imprimer demande examens complementaires"
      style={primaryActionButtonStyle()}
      onMouseEnter={primaryActionBtnEnter}
      onMouseLeave={primaryActionBtnLeave}>
      <svg width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
        <path d="M6 9V2h12v7M6 18H4a2 2 0 01-2-2v-5a2 2 0 012-2h16a2 2 0 012 2v5a2 2 0 01-2 2h-2"/>
        <rect x="6" y="14" width="12" height="8"/>
      </svg>
      Imprimer examens complementaires
    </button>
  );
}